    You are given a list of two strings, both strings consist of open
    parentheses '(' or close parentheses ')' only.
    Your job is to check if it is possible to concatenate the two strings in
    some order, that the resulting string will be good.
    A string S is considered to be good if and only if all parentheses in S
    are balanced. For example: the string '(())()' is good, while the string
    '())' is not.
    Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.

    Examples:
    match_parens(['()(', ')']) == 'Yes'
    match_parens([')', ')']) == 'No'
    '''
    s1, s2 = lst
    total_len = len(s1) + len(s2)
    if total_len % 2 != 0:
        return 'No'

    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Check both possible concatenations
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'

    # Check if the first string can be split into two parts where the first part
    # is balanced and the second part is balanced when combined with the second string
    # or vice versa
    balance = 0
    for char in s1:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance == 0:
            # Check if the remaining part of s1 and s2 can be balanced
            if is_balanced(s1[len(s1) - balance:] + s2) or is_balanced(s2 + s1[:balance]):
                return 'Yes'

    # Check the same for the second string
    balance = 0
    for char in s2:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance == 0:
            # Check if the remaining part of s2 and s1 can be balanced
            if is_balanced(s2[len(s2) - balance:] + s1) or is_balanced(s1 + s2[:balance]):
                return 'Yes'

    return 'No'
