import re

def valid_date(date):
    """Validates a given date string according to specified rules."""
    if not date:
        return False

    # Check format using regex (mm-dd-yyyy)
    if not re.fullmatch(r'\d{2}-\d{2}-\d{4}', date):
        return False

    month, day, year = map(int, date.split('-'))

    # Check month range
    if month < 1 or month > 12:
        return False

    # Check day range based on month
    if month in {1, 3, 5, 7, 8, 10, 12}:
        if day < 1 or day > 31:
            return False
    elif month in {4, 6, 9, 11}:
        if day < 1 or day > 30:
            return False
    else:  # February
        if day < 1 or day > 29:
            return False

    return True
